package com.galleryvote.vote;
import static org.assertj.core.api.Assertions.assertThatThrownBy; import static org.mockito.Mockito.*; import com.galleryvote.contest.Contest; import com.galleryvote.submission.*; import com.galleryvote.user.*; import java.time.Instant; import java.util.Optional; import org.junit.jupiter.api.Test; import org.springframework.web.server.ResponseStatusException;
class VoteServiceTest { @Test void rejectsSelfVote(){VoteRepository votes=mock(VoteRepository.class);SubmissionRepository submissions=mock(SubmissionRepository.class);UserRepository users=mock(UserRepository.class);User owner=mock(User.class);Submission submission=mock(Submission.class);when(owner.getId()).thenReturn(1L);when(submission.getAuthor()).thenReturn(owner);when(submissions.findById(2L)).thenReturn(Optional.of(submission));assertThatThrownBy(()->new VoteService(votes,submissions,users).cast(1L,2L)).isInstanceOf(ResponseStatusException.class);verifyNoInteractions(votes);} }
